<script setup lang="ts">
import {onMounted,ref,watch} from 'vue';
import {supabase} from '@/lib/supabase';
import {formatPen,limaDate} from '@/lib/financeMoney';
import {receiptDate,receiptMethods} from '@/lib/financeReceipts';
defineProps<{zones:{id:string;name:string}[]}>();
const emit=defineEmits<{receipt:[id:string]}>();
type Event={id:string;receipt_number:string|null;occurred:string;date_only?:boolean;amount:string;kind:string;collector_id:string;actor_id:string;method:string;reference:string|null;collector:string;customer:string;contract:string;zone:string;reversed_at:string|null};
type Totals={received:string;reversed:string;net:string;advancesReceived:string;payments:number;reversals:number};
type Report={rows:Event[];total:number;totals:Totals;methods:({method:string}&Pick<Totals,'received'|'reversed'|'net'>)[];administrators:({collector_id:string;collector:string}&Pick<Totals,'received'|'reversed'|'net'>)[];collectors:{id:string;name:string}[]};
const from=ref(limaDate()),to=ref(limaDate()),zone=ref(''),collector=ref(''),page=ref(1),busy=ref(false),error=ref(''),report=ref<Report|null>(null),collectors=ref<{id:string;name:string}[]>([]);
const args=(n=page.value)=>({p_from:from.value,p_to:to.value,p_zone:zone.value||null,p_collector:collector.value||null,p_page:n});
async function read(parameters:ReturnType<typeof args>){const {data,error:e}=await supabase.rpc('finance_daily_collections',parameters);if(e)throw Error(e.message);return data as Report;}
async function load(reset=false){if(busy.value)return;if(reset)page.value=1;busy.value=true;error.value='';try{const request=args();const data=await read(request);if(JSON.stringify(request)===JSON.stringify(args())){report.value=data;collectors.value=data.collectors;}}catch(e){report.value=null;error.value=String(e);}finally{busy.value=false;}}
defineExpose({refresh:load});onMounted(()=>void load());watch([from,to,zone,collector],()=>{report.value=null;page.value=1;});
async function exportCsv(){if(!report.value||busy.value)return;busy.value=true;error.value='';try{const total=report.value.total;if(total>20000)throw Error('Acota el período o responsable: máximo 20000 movimientos por exportación.');const parameters=args(),rows:Event[]=[];for(let n=1;n<=Math.ceil(total/50);n++)rows.push(...(await read({...parameters,p_page:n})).rows);const values=[['Fecha Perú','Recibo','Evento','Importe con signo PEN','Medio','Operación','Responsable del cobro','Actor del evento','Cliente','Contrato','PON original'],...rows.map(r=>[r.date_only?new Date(r.occurred).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):receiptDate(r.occurred),r.receipt_number??'Sin recibo numerado',r.kind==='reversed'?'Reverso':'Cobro recibido',r.amount,receiptMethods[r.method],r.reference,r.collector,r.actor_id,r.customer,r.contract,r.zone])];const safe=(v:unknown,column:number)=>{let text=String(v??'');if(column===5&&text)text="'"+text;else if(!(column===3&&/^-?\d+(\.\d{1,2})?$/.test(text)))text=text.replace(/^\s*[=+@-]/,"'");return '"'+text.replaceAll('"','""')+'"';};const url=URL.createObjectURL(new Blob(['\uFEFF'+values.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`cobranza-diaria-${parameters.p_from}-${parameters.p_to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=String(e);}finally{busy.value=false;}}
</script>
<template><section class="daily-collections"><div class="finance-table-tools"><h2>Control diario de cobranza</h2><button class="btn-ghost" :disabled="busy||!report" @click="exportCsv">Exportar movimientos a Excel (CSV)</button></div><form class="finance-filters" @submit.prevent="load(true)"><label>Desde<input v-model="from" type="date" required></label><label>Hasta<input v-model="to" type="date" required></label><label>PON original<select v-model="zone" aria-label="PON del control diario"><option value="">Todas</option><option v-for="z in zones" :key="z.id" :value="z.id">{{z.name}}</option></select></label><label>Responsable del cobro<select v-model="collector" aria-label="Responsable del control diario"><option value="">Todos</option><option v-for="c in collectors" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="btn-secondary" :disabled="busy">{{busy?'Consultando…':'Actualizar control diario'}}</button></form><p class="finance-help">America/Lima · hasta 31 días · el reverso se atribuye al responsable del cobro original; su actor se conserva por separado. Descuentos, exoneraciones y aplicaciones de anticipos no son cobros nuevos.</p><p v-if="error" role="alert" class="finance-error">{{error}}</p><template v-if="report"><div class="finance-metrics daily-metrics"><article><span>Dinero recibido</span><strong>{{formatPen(report.totals.received)}}</strong><small>{{report.totals.payments}} pagos · incluye anticipos recibidos</small></article><article><span>Pagos revertidos</span><strong>{{formatPen(report.totals.reversed)}}</strong><small>{{report.totals.reversals}} reversos por su fecha efectiva</small></article><article><span>Recaudación neta</span><strong>{{formatPen(report.totals.net)}}</strong><small>Recibido menos reversado</small></article><article><span>Anticipos generados al cobrar</span><strong>{{formatPen(report.totals.advancesReceived)}}</strong><small>Parte del recibido; no sumar nuevamente</small></article></div><div class="finance-grid"><article class="finance-panel"><h2>Por medio de pago</h2><div class="finance-table"><table><thead><tr><th>Medio</th><th>Recibido</th><th>Revertido</th><th>Neto</th></tr></thead><tbody><tr v-for="m in report.methods" :key="m.method"><td>{{receiptMethods[m.method]}}</td><td>{{formatPen(m.received)}}</td><td>{{formatPen(m.reversed)}}</td><td>{{formatPen(m.net)}}</td></tr></tbody></table></div></article><article class="finance-panel"><h2>Por administrador</h2><div class="finance-table"><table><thead><tr><th>Responsable</th><th>Recibido</th><th>Revertido</th><th>Neto</th></tr></thead><tbody><tr v-for="(a,n) in report.administrators" :key="n"><td>{{a.collector}}</td><td>{{formatPen(a.received)}}</td><td>{{formatPen(a.reversed)}}</td><td>{{formatPen(a.net)}}</td></tr></tbody></table></div></article></div><div class="finance-table daily-events"><table><thead><tr><th>Fecha Perú / recibo</th><th>Evento</th><th>Cliente / contrato</th><th>PON original</th><th>Medio / operación</th><th>Importe PEN</th><th>Responsable / actor</th><th>Acción</th></tr></thead><tbody><tr v-for="r in report.rows" :key="r.id+r.kind"><td>{{r.date_only?new Date(r.occurred).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):receiptDate(r.occurred)}}<small>{{r.receipt_number??'Pago anterior sin recibo numerado'}}</small></td><td>{{r.kind==='reversed'?'Reverso':'Recibido'}}<small v-if="r.kind==='received'&&r.reversed_at">Tiene reverso posterior</small></td><td>{{r.customer}}<small>{{r.contract}}</small></td><td>{{r.zone??'Sin PON congelada'}}</td><td>{{receiptMethods[r.method]}}<small>{{r.reference||'Sin referencia de efectivo'}}</small></td><td class="finance-number">{{formatPen(r.amount)}}</td><td>{{r.collector}}<small :title="r.actor_id">Actor {{r.actor_id.slice(0,8)}}…</small></td><td><button v-if="r.receipt_number" class="finance-link" @click="emit('receipt',r.id)">Ver recibo</button></td></tr><tr v-if="!report.rows.length"><td colspan="8" class="finance-empty">Sin movimientos monetarios para los filtros.</td></tr></tbody></table></div><div class="finance-pagination"><span>{{report.total}} movimientos · página {{page}} · 50 por página</span><button :disabled="busy||page===1" @click="page--;load()">Anterior</button><button :disabled="busy||page*50>=report.total" @click="page++;load()">Siguiente</button></div><p class="finance-help">Exportación explícita de eventos del período, sin generar otro libro de caja. Para un cierre definitivo verifica que no haya operaciones concurrentes.</p></template></section></template>
<style scoped>.daily-collections{min-width:0}.daily-collections h2{font-size:16px;font-weight:650}.daily-metrics{margin-top:8px}.daily-collections .finance-grid{grid-template-columns:1fr 1fr}@media(max-width:850px){.daily-collections .finance-grid{grid-template-columns:1fr}}</style>
